import java.util.*;
import java.io.*;

public class D {
    static final int MOD = 1000000007;
    static int[][] memo;

    static int value(int row, int col) {
        if (memo[row][col] != -1) {
            return memo[row][col];
        }

        int result;
        if (col == 0) {
            result = 1;
        } else {
            int left = value(row, col - 1);
            int up = (row > col) ? value(row - 1, col) : 0;
            result = (left + up) % MOD;
        }

        memo[row][col] = result;
        return result;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(new StringTokenizer(in.readLine()).nextToken());
        memo = new int[n + 1][n + 1];

        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }

        long sum = 0;
        for (int row = 0; row <= n; row++) {
            if ((row & 1) == 1) {
                sum = (sum + value(row, 0)) % MOD;
            }
        }

        for (int row = 1; row <= n; row++) {
            for (int col = 1; col <= row; col++) {
                if (((row + col) & 1) == 1) {
                    sum = (sum + value(row, col)) % MOD;
                }
            }
        }

        System.out.println(sum);
    }
}
